package io.github.proify.qrckit.decrypt

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull

class QrcEncrypterTest {

    /**
     * 真实 QRC 密文样本（QQ 音乐《义勇军进行曲》，1224 字节密文）。
     * 用于验证加密方向能逐字节还原原始密文。
     */
    private val sample =
        ""

    @Test
    fun roundTripPreservesPlainText() {
        val plain = """<?xml version="1.0" encoding="utf-8"?>
<QrcInfos>
<QrcHeadInfo SaveTime="0" Version="100"/>
<LyricInfo LyricCount="1">
<Lyric_1 LyricType="1" LyricContent="[ti:test]
[ar:test]
[0,1000]你(0,500)好(500,500)
"/>
</LyricInfo>
</QrcInfos>"""

        val cipher = assertNotNull(QrcEncrypter.encrypt(plain), "encrypt 返回 null")
        assertEquals(plain, QrcDecrypter.decrypt(cipher), "加解密往返后明文不一致")
    }

    @Test
    fun reEncryptReproducesOriginalCipher() {
        val plain = assertNotNull(QrcDecrypter.decrypt(sample), "样本解密失败")
        assertEquals(sample.uppercase(), QrcEncrypter.encrypt(plain), "重新加密未能还原原始密文")
    }
}
